        v2 = XXH32_round(v2, XXH_readLE32(base.add(4) as *const c_void, endian));
        v3 = XXH32_round(v3, XXH_readLE32(base.add(8) as *const c_void, endian));
        v4 = XXH32_round(v4, XXH_readLE32(base.add(12) as *const c_void, endian));
    }

    if !remaining.is_empty() {
        (*state).v1 = v1 as uint32_t;
        (*state).v2 = v2 as uint32_t;
        (*state).v3 = v3 as uint32_t;
        (*state).v4 = v4 as uint32_t;
