        (*state).v2 = v2 as uint32_t;
        (*state).v3 = v3 as uint32_t;
        (*state).v4 = v4 as uint32_t;
    }

    let tail = chunks.remainder();
    if !tail.is_empty() {
        XXH_memcpy(
            &raw mut (*state).mem32 as *mut uint32_t as *mut c_void,
            tail.as_ptr() as *const c_void,
            tail.len() as size_t,
